import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { mobileAssetUrl } from "@/lib/props-store";
export function OPTIONS(){return mobileOptions()}
export async function GET(request){try{const session=await requireMobileUser(request),user=await prisma.user.findUniqueOrThrow({where:{id:session.id},select:{id:true,publicId:true,sessionVersion:true}}),items=await prisma.userGiftInventory.findMany({where:{userId:user.id,quantity:{gt:0}},include:{giftAsset:true},orderBy:{updatedAt:"desc"}});return mobileJson({success:true,data:{items:items.map(i=>({giftId:i.giftAsset.publicId,name:i.giftAsset.name,mimeType:i.giftAsset.mimeType,mediaUrl:mobileAssetUrl(request,i.giftAsset,user),quantity:i.quantity}))}})}catch(e){return mobileApiError(e,"BACKPACK_READ_FAILED")}}
